#!/usr/bin/env dotnet
#:property AllowUnsafeBlocks=true

Console.WriteLine($"nint size: {nint.Size} bytes");

// stackalloc Span<nint>
Span<nint> nints = stackalloc nint[5];
for (int i = 0; i < nints.Length; i++)
    nints[i] = i * 10;

Console.WriteLine("Span<nint> via stackalloc:");
for (int i = 0; i < nints.Length; i++)
    Console.WriteLine($"  [{i}] = {nints[i]}");

// stackalloc Span<nuint>
Span<nuint> nuints = stackalloc nuint[3];
nuints[0] = 100;
nuints[1] = 200;
nuints[2] = 300;

Console.WriteLine("Span<nuint> via stackalloc:");
for (int i = 0; i < nuints.Length; i++)
    Console.WriteLine($"  [{i}] = {nuints[i]}");

